using System;using System.Drawing;using System.Windows.Forms;using AshkanJobCenter.Core;using AshkanJobCenter.Data;
namespace AshkanJobCenter.UI{public class UserProfilePage:UserControl{Label info,status;public UserProfilePage(){Dock=DockStyle.Fill;BackColor=Theme.Background;Padding=new Padding(22);Build();}void Build(){var title=Ui.Label(L.Fa?"پروفایل و حساب کاربری":"Profile & account",22,true);title.Dock=DockStyle.Top;title.Height=50;Controls.Add(title);var card=new Panel{Dock=DockStyle.Top,Height=300,BackColor=Color.White,Padding=new Padding(24)};Controls.Add(card);card.BringToFront();var avatar=new Label{Text=Initials(),Width=86,Height=86,BackColor=Theme.Primary,ForeColor=Color.White,Font=new Font("Segoe UI",22,FontStyle.Bold),TextAlign=ContentAlignment.MiddleCenter,Dock=DockStyle.Top};card.Controls.Add(avatar);info=Ui.Label(AppSession.FullName+Environment.NewLine+AppSession.Role+Environment.NewLine+(L.Fa?"شناسه کاربری: ":"User ID: ")+AppSession.UserId,12);info.Dock=DockStyle.Top;info.Height=90;info.TextAlign=ContentAlignment.MiddleCenter;card.Controls.Add(info);var logout=Ui.Button(L.Fa?"خروج امن از حساب":"Secure sign out",true);logout.Dock=DockStyle.Bottom;logout.Height=44;logout.Click+=(s,e)=>{Database.Audit("Logout","Session","User signed out");Application.Restart();};card.Controls.Add(logout);status=Ui.Label(L.Fa?"نشست فعال و محافظت‌شده است.":"Your session is active and protected.",10);status.ForeColor=Theme.Muted;status.Dock=DockStyle.Bottom;status.Height=34;card.Controls.Add(status);}string Initials(){var s=(AppSession.FullName??"AJ").Trim();if(s.Length==0)return"AJ";var p=s.Split(' ');return p.Length>1?(p[0].Substring(0,1)+p[p.Length-1].Substring(0,1)).ToUpper():s.Substring(0,Math.Min(2,s.Length)).ToUpper();}}}
